insert into products (id, name, description, price_minor, currency, images, category_id, featured, created_at) values
  ('studio-headphones', 'Studio Over-Ear Headphones', 'Closed-back over-ears with 40 hours of battery, adaptive noise cancellation, and a fold-flat frame.', 24900, 'USD', '["https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=900&q=80","https://images.unsplash.com/photo-1484704849700-f032a568e944?w=900&q=80"]'::jsonb, 'audio', true, '2026-06-26T10:00:00.000Z'),
  ('true-wireless-earbuds', 'True Wireless Earbuds', 'Compact earbuds with wireless charging, transparency mode, and six hours per charge.', 12900, 'USD', '["https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=900&q=80","https://images.unsplash.com/photo-1572569511254-d8f925fe2cbb?w=900&q=80"]'::jsonb, 'audio', false, '2026-07-09T10:00:00.000Z'),
  ('bookshelf-speaker', 'Bookshelf Speaker', 'A warm, room-filling speaker in a real wood cabinet with Bluetooth and phono input.', 19900, 'USD', '["https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=900&q=80","https://images.unsplash.com/photo-1545454675-3531b543be5d?w=900&q=80"]'::jsonb, 'audio', false, '2026-05-12T10:00:00.000Z'),
  ('usb-microphone', 'USB Condenser Microphone', 'Broadcast-quality cardioid mic with onboard gain, mute, and a desktop stand. Plug and talk.', 15900, 'USD', '["https://images.unsplash.com/photo-1590602847861-f357a9332bbc?w=900&q=80","https://images.unsplash.com/photo-1583394838336-acd977736f90?w=900&q=80"]'::jsonb, 'audio', false, '2026-04-20T10:00:00.000Z'),
  ('ultrabook-14', '14-inch Ultrabook', 'A 1.2 kg aluminum laptop with a 2.8K display, 18-hour battery, and a fanless design.', 129900, 'USD', '["https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=900&q=80","https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=900&q=80"]'::jsonb, 'computers', true, '2026-06-18T10:00:00.000Z'),
  ('mechanical-keyboard', 'Mechanical Keyboard', 'Hot-swappable switches, PBT keycaps, and a gasket-mounted deck that sounds as good as it feels.', 9900, 'USD', '["https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=900&q=80","https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?w=900&q=80"]'::jsonb, 'computers', false, '2026-07-01T10:00:00.000Z'),
  ('wireless-mouse', 'Wireless Ergonomic Mouse', 'A sculpted mouse with silent clicks, three-device pairing, and months of battery life.', 4900, 'USD', '["https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=900&q=80","https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?w=900&q=80"]'::jsonb, 'computers', false, '2026-05-25T10:00:00.000Z'),
  ('usb-c-dock', 'USB-C Docking Station', 'One cable to dual 4K displays, gigabit ethernet, and 100W passthrough charging.', 8900, 'USD', '["https://images.unsplash.com/photo-1588508065123-287b28e013da?w=900&q=80","https://images.unsplash.com/photo-1625723044792-44de16ccb4e9?w=900&q=80"]'::jsonb, 'computers', false, '2026-03-30T10:00:00.000Z'),
  ('smartphone-pro', 'Smartphone Pro', 'A 6.4-inch OLED flagship with a three-camera system, all-day battery, and five years of updates.', 99900, 'USD', '["https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=900&q=80","https://images.unsplash.com/photo-1601784551446-20c9e07cdbdb?w=900&q=80"]'::jsonb, 'phones-tablets', true, '2026-06-30T10:00:00.000Z'),
  ('tablet-11', '11-inch Tablet', 'A thin, bright 120Hz tablet for sketching, streaming, and split-screen work. Pencil sold separately.', 64900, 'USD', '["https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=900&q=80","https://images.unsplash.com/photo-1561154464-82e9adf32764?w=900&q=80"]'::jsonb, 'phones-tablets', false, '2026-05-18T10:00:00.000Z'),
  ('e-reader', 'E-Reader', 'A glare-free 300 ppi display, adjustable warm light, and weeks of battery. Your library in one hand.', 14900, 'USD', '["https://images.unsplash.com/photo-1592496431122-2349e0fbc666?w=900&q=80","https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=900&q=80"]'::jsonb, 'phones-tablets', false, '2026-04-12T10:00:00.000Z'),
  ('magsafe-power-bank', 'Magnetic Power Bank', 'A slim 5,000 mAh battery that snaps to the back of your phone and charges wirelessly.', 5900, 'USD', '["https://images.unsplash.com/photo-1609091839311-d5365f9ff1c5?w=900&q=80","https://images.unsplash.com/photo-1541877944-ac82a091518a?w=900&q=80"]'::jsonb, 'phones-tablets', false, '2026-07-11T10:00:00.000Z'),
  ('mirrorless-camera', 'Mirrorless Camera', 'A full-frame body with in-body stabilization, 4K60 video, and dual card slots. Lens not included.', 149900, 'USD', '["https://images.unsplash.com/photo-1516035069371-29a1b244cc32?w=900&q=80","https://images.unsplash.com/photo-1502920917128-1aa500764cbd?w=900&q=80"]'::jsonb, 'cameras', true, '2026-06-05T10:00:00.000Z'),
  ('instant-camera', 'Instant Camera', 'Point, shoot, and watch the print develop in your hand. Auto exposure keeps every shot usable.', 9900, 'USD', '["https://images.unsplash.com/photo-1526170375885-4d8ecf77b99f?w=900&q=80","https://images.unsplash.com/photo-1495707902641-75cac588d2e9?w=900&q=80"]'::jsonb, 'cameras', false, '2026-05-08T10:00:00.000Z'),
  ('action-camera', '4K Action Camera', 'Waterproof to 10 m with horizon lock and hypersmooth stabilization. Built for the mountain.', 39900, 'USD', '["https://images.unsplash.com/photo-1518183214770-9cffbec72538?w=900&q=80","https://images.unsplash.com/photo-1498049794561-7780e7231661?w=900&q=80"]'::jsonb, 'cameras', false, '2026-04-25T10:00:00.000Z'),
  ('travel-tripod', 'Carbon Travel Tripod', 'Folds to 40 cm, weighs under a kilo, and holds steady in wind. A ball head is included.', 6900, 'USD', '["https://images.unsplash.com/photo-1542567455-cd733f23fbb1?w=900&q=80","https://images.unsplash.com/photo-1617953141905-b27fb1f17d88?w=900&q=80"]'::jsonb, 'cameras', false, '2026-03-14T10:00:00.000Z'),
  ('wireless-controller', 'Wireless Controller', 'Low-latency wireless with hall-effect sticks, remappable paddles, and a 40-hour battery.', 6900, 'USD', '["https://images.unsplash.com/photo-1606144042614-b2417e99c4e3?w=900&q=80","https://images.unsplash.com/photo-1592840496694-26d035b52b48?w=900&q=80"]'::jsonb, 'gaming', false, '2026-06-10T10:00:00.000Z'),
  ('gaming-headset', 'Gaming Headset', 'Spatial audio, a flip-to-mute mic, and memory foam that survives marathon sessions.', 8900, 'USD', '["https://images.unsplash.com/photo-1599669454699-248893623440?w=900&q=80","https://images.unsplash.com/photo-1612287230202-1ff1d85d1bdf?w=900&q=80"]'::jsonb, 'gaming', false, '2026-05-30T10:00:00.000Z'),
  ('vr-headset', 'VR Headset', 'Standalone VR with inside-out tracking, pancake lenses, and a growing native library.', 39900, 'USD', '["https://images.unsplash.com/photo-1593508512255-86ab42a8e620?w=900&q=80","https://images.unsplash.com/photo-1617802690992-15d93263d3a9?w=900&q=80"]'::jsonb, 'gaming', true, '2026-06-22T10:00:00.000Z'),
  ('retro-console', 'Retro Mini Console', 'Fifty classics built in, two wired controllers, and HDMI out. Instant nostalgia.', 9900, 'USD', '["https://images.unsplash.com/photo-1531525645387-7f14be1bdbbd?w=900&q=80","https://images.unsplash.com/photo-1486572788966-cfd3df1f5b42?w=900&q=80"]'::jsonb, 'gaming', false, '2026-04-02T10:00:00.000Z'),
  ('smart-speaker', 'Smart Speaker', 'Room-adaptive sound with a built-in voice assistant and a physical mic-off switch.', 9900, 'USD', '["https://images.unsplash.com/photo-1543512214-318c7553f230?w=900&q=80","https://images.unsplash.com/photo-1512446816042-444d641267d4?w=900&q=80"]'::jsonb, 'smart-home', false, '2026-06-14T10:00:00.000Z'),
  ('smart-bulb-kit', 'Smart Bulb Starter Kit', 'Two color-changing bulbs and a hub. Schedules, scenes, and sunrise alarms included.', 4900, 'USD', '["https://images.unsplash.com/photo-1565814329452-e1efa11c5b89?w=900&q=80","https://images.unsplash.com/photo-1550985616-10810253b84d?w=900&q=80"]'::jsonb, 'smart-home', false, '2026-05-02T10:00:00.000Z'),
  ('security-camera', 'Indoor Security Camera', '2K video with night vision, person alerts, and local storage. No subscription required.', 12900, 'USD', '["https://images.unsplash.com/photo-1558002038-1055907df827?w=900&q=80","https://images.unsplash.com/photo-1550009158-9ebf69173e03?w=900&q=80"]'::jsonb, 'smart-home', false, '2026-07-06T10:00:00.000Z'),
  ('robot-vacuum', 'Robot Vacuum', 'Lidar mapping, 4,000 Pa suction, and self-emptying for up to 60 days. Floors on autopilot.', 39900, 'USD', '["https://images.unsplash.com/photo-1589820296156-2454bb8a6ad1?w=900&q=80","https://images.unsplash.com/photo-1603618090561-412154b4bd1b?w=900&q=80"]'::jsonb, 'smart-home', false, '2026-03-08T10:00:00.000Z');
